<?php
declare(strict_types=1);
require_once __DIR__ . '/../services/AdminCompetitionService.php';
require_once __DIR__ . '/../scripts/migrate_admin_management.php';
$pdo=db();$driver=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME);
$namespace=$pdo->query($driver==='pgsql'?'SELECT current_schema()':'SELECT DATABASE()')->fetchColumn();
if(!preg_match('/^interclasse_admin_test_[a-z0-9_]+$/',(string)$namespace))throw new RuntimeException('Use exclusivamente uma cópia isolada interclasse_admin_test_*.');
migrate_admin_management($pdo);
