start_app_session();$_SESSION['user_id']=$actor['id'];$_SESSION['last_activity_at']=time();
$service=new AdminCompetitionService();$passed=0;
function check(bool $ok,string $name):void{global $passed;if(!$ok)throw new RuntimeException('FAIL '.$name);$passed++;echo "PASS $name\n";}
function operation(array $command):array{global $service,$actor;$preview=$service->preview($command,$actor);if(!$preview['can_execute'])throw new RuntimeException('Prévia insegura: '.json_encode($preview));return $service->execute($preview['preview_id'],'Validação administrativa automatizada',$preview['confirmation_word'],$actor);}
function matchRow(int $id):array{global $service;return $service->snapshot()['matches'][$id];}
function fixture(string $mod='fifa',int $count=4,string $format='simple',string $gender='masculino'):array{
    global $pdo,$actor;$suffix=bin2hex(random_bytes(4));$stmt=$pdo->prepare('INSERT INTO events(name,created_by,start_date,status) VALUES(?,?,CURRENT_DATE,"encerrado")');$stmt->execute(['Teste admin '.$suffix,$actor['id']]);$event=(int)$pdo->lastInsertId();
    $d=modality_definition($mod);$stmt=$pdo->prepare('INSERT INTO event_modalities(event_id,modality,score_type,bracket_type,max_players_per_team,set_best_of,set_points,rules_json) VALUES(?,?,?,?,?,?,?,?)');$stmt->execute([$event,$mod,$d['score_type'],$format,2,3,25,isset($d['rules'])?json_encode($d['rules']):null]);$teams=[];$players=[];$classes=[];
    for($i=0;$i<$count;$i++){$name='QA '.$suffix.' '.$i;$pdo->prepare('INSERT INTO classes(name) VALUES(?)')->execute([$name]);$classes[]=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO teams(event_id,modality,name,class_name,gender,group_name) VALUES(?,?,?,?,?,?)')->execute([$event,$mod,$name,$name,$gender,'A']);$team=(int)$pdo->lastInsertId();$teams[]=$team;$pdo->prepare('INSERT INTO players(team_id,name) VALUES(?,?)')->execute([$team,'Atleta '.$i.' '.$suffix]);$players[]=(int)$pdo->lastInsertId();}
    return ['event'=>$event,'mod'=>$mod,'teams'=>$teams,'players'=>$players,'classes'=>$classes,'gender'=>$gender];
}
function createMatch(array $f,int $home=0,int $away=1,string $stage='grupo',array $extra=[]):int{
    global $service;$before=$service->snapshot()['matches'];$data=['event_id'=>$f['event'],'modality'=>$f['mod'],'gender'=>$f['gender'],'stage'=>$stage,'home_team_id'=>$f['teams'][$home],'away_team_id'=>$f['teams'][$away],'status'=>'agendada'];if(is_individual_modality($f['mod'])){$data['home_player_id']=$f['players'][$home];$data['away_player_id']=$f['players'][$away];}
    operation(['operation'=>'save_match','id'=>0,'data'=>array_replace($data,$extra),'policy'=>'update']);return (int)array_key_first(array_diff_key($service->snapshot()['matches'],$before));
}

$f=fixture();$first=createMatch($f);operation(['operation'=>'save_match','id'=>$first,'data'=>['place'=>'Quadra revisada','starts_at'=>'2026-10-20T10:30'],'policy'=>'update']);check(matchRow($first)['place']==='Quadra revisada','1 editar antes do início em evento encerrado');
operation(['operation'=>'save_match','id'=>$first,'data'=>['status'=>'encerrada','home_score'=>3,'away_score'=>1],'policy'=>'update']);operation(['operation'=>'save_match','id'=>$first,'data'=>['home_score'=>4],'policy'=>'update']);check(matchRow($first)['home_score']===4,'2 corrigir placar finalizado');
$parent=createMatch($f,0,1,'quartas',['status'=>'encerrada','home_score'=>2,'away_score'=>0]);$other=createMatch($f,2,3,'quartas',['status'=>'encerrada','home_score'=>2,'away_score'=>0]);
$semi=createMatch($f,0,2,'semifinal',['home_source_match_id'=>$parent,'away_source_match_id'=>$other,'status'=>'encerrada','home_score'=>2,'away_score'=>0]);
$final=createMatch($f,0,3,'final',['home_source_match_id'=>$semi,'status'=>'encerrada','home_score'=>2,'away_score'=>0]);
$descendantsBefore=[matchRow($semi),matchRow($final)];operation(['operation'=>'save_match','id'=>$parent,'data'=>['home_score'=>4],'policy'=>'update']);check($descendantsBefore===[matchRow($semi),matchRow($final)],'correção com mesmo classificado preserva resultados posteriores');
$preview=$service->preview(['operation'=>'save_match','id'=>$parent,'data'=>['home_score'=>0,'away_score'=>3],'policy'=>'update'],$actor);check(!$preview['can_execute']&&$preview['impact']['match_count']>=3,'3 prévia identifica semifinal e final já disputadas');
operation(['operation'=>'save_match','id'=>$parent,'data'=>['home_score'=>0,'away_score'=>3],'policy'=>'manual']);check(matchRow($semi)['review_state']==='needs_review'&&matchRow($final)['winner_player_id']===null,'4 corrigir ancestral e pausar final incompatível');
check(!in_array($semi,array_column($pdo->query('SELECT id FROM matches')->fetchAll(),'id'),true),'partidas em revisão excluídas das consultas operacionais');
$manual=createMatch($f,1,3,'repescagem');check(matchRow($manual)['status']==='agendada','5 criar confronto após gerar fases');
$arch=operation(['operation'=>'archive','entity'=>'matches','id'=>$manual,'policy'=>'restart']);check(matchRow($manual)['archived_at']!==null,'6 arquivar sem resultados');
operation(['operation'=>'restore_operation','operation_id'=>$arch['operation_id'],'policy'=>'update']);check(matchRow($manual)['archived_at']===null,'restaurar operação preserva ID');
operation(['operation'=>'archive','entity'=>'matches','id'=>$other,'policy'=>'manual']);check(matchRow($other)['home_score']===2&&matchRow($other)['archived_at']!==null,'7 arquivar resultado sem apagar histórico');
$beforeTeams=count($service->snapshot()['teams']);$className='Nova QA '.bin2hex(random_bytes(3));operation(['operation'=>'save_entity','entity'=>'classes','data'=>['name'=>$className],'policy'=>'update']);operation(['operation'=>'save_entity','entity'=>'teams','data'=>['name'=>$className,'class_name'=>$className,'event_id'=>$f['event'],'modality'=>'fifa','gender'=>'masculino','group_name'=>'A'],'policy'=>'update']);check(count($service->snapshot()['teams'])===$beforeTeams+1,'8 inscrever turma após geração');
$addedTeam=(int)max(array_keys($service->snapshot()['teams']));operation(['operation'=>'archive','entity'=>'teams','id'=>$addedTeam,'policy'=>'update']);check($service->snapshot()['teams'][$addedTeam]['archived_at']!==null,'9 remover inscrição com partidas futuras');
operation(['operation'=>'archive','entity'=>'teams','id'=>$f['teams'][2],'policy'=>'manual']);check($service->snapshot()['players'][$f['players'][2]]['archived_at']!==null,'10 remover equipe que já disputou partidas');
operation(['operation'=>'save_entity','entity'=>'players','id'=>$f['players'][1],'data'=>['team_id'=>$f['teams'][3]],'policy'=>'manual']);check($service->snapshot()['players'][$f['players'][1]]['team_id']===$f['teams'][3],'11 transferir jogador sem recriar sua identidade');
$g=fixture('clash_royale',4);operation(['operation'=>'regenerate','event_id'=>$g['event'],'modality'=>'clash_royale','mode'=>'all','kind'=>'simple','policy'=>'restart']);$matches=array_filter($service->snapshot()['matches'],fn($m)=>$m['event_id']===$g['event']&&!$m['archived_at']);check(count($matches)===3,'12 regeneração produz uma chave única');
$before=$service->snapshot();$p=$service->preview(['operation'=>'save_entity','entity'=>'players','id'=>$g['players'][0],'data'=>['name'=>'Não confirmar'],'policy'=>'update'],$actor);check($before===$service->snapshot(),'13 cancelar prévia não altera entidades');
$service->beforeCommit=fn()=>throw new RuntimeException('Falha simulada');try{$service->execute($p['preview_id'],'Falha de teste',null,$actor);throw new RuntimeException('Falha não injetada');}catch(RuntimeException $error){if($error->getMessage()!=='Falha simulada')throw $error;}finally{$service->beforeCommit=null;}check($before===$service->snapshot(),'14 rollback integral após falha');
$teacher=$pdo->query('SELECT id,role FROM users WHERE role<>"admin" LIMIT 1')->fetch();try{$service->preview(['operation'=>'archive','entity'=>'players','id'=>$g['players'][0]],$teacher);throw new RuntimeException('Autorização incorreta');}catch(AdminOperationException $error){check($error->httpStatus===403,'15 perfil comum não recebe privilégios');}
$result=$service->execute($p['preview_id'],'Persistência e auditoria',null,$actor);$duplicate=$service->execute($p['preview_id'],'Repetição segura',null,$actor);check($duplicate['duplicate']&&$service->snapshot()['players'][$g['players'][0]]['name']==='Não confirmar','16 persistência e execução idempotente');
$stale=$service->preview(['operation'=>'save_entity','entity'=>'players','id'=>$g['players'][0],'data'=>['name'=>'Prévia antiga'],'policy'=>'update'],$actor);operation(['operation'=>'save_entity','entity'=>'players','id'=>$g['players'][1],'data'=>['name'=>'Alteração concorrente'],'policy'=>'update']);try{$service->execute($stale['preview_id'],'Concorrência',null,$actor);throw new RuntimeException('Prévia obsoleta aplicada');}catch(AdminOperationException $error){check($error->httpStatus===409,'prévia concorrente rejeitada');}
$expired=$service->preview(['operation'=>'archive','entity'=>'players','id'=>$g['players'][2],'policy'=>'manual'],$actor);$pdo->prepare('UPDATE admin_operation_previews SET expires_at=? WHERE id=?')->execute(['2020-01-01 00:00:00',$expired['preview_id']]);try{$service->execute($expired['preview_id'],'Expirada',null,$actor);throw new RuntimeException('Expirada aplicada');}catch(AdminOperationException $error){check($error->httpStatus===409,'prévia vencida rejeitada');}
$purge=operation(['operation'=>'purge','entity'=>'players','id'=>$g['players'][3],'policy'=>'manual']);check(!isset($service->snapshot()['players'][$g['players'][3]]),'exclusão definitiva registrada');operation(['operation'=>'restore_operation','operation_id'=>$purge['operation_id'],'policy'=>'manual']);check(isset($service->snapshot()['players'][$g['players'][3]]),'recuperação após exclusão definitiva');
$active=array_values(array_filter($service->snapshot()['matches'],fn($m)=>$m['event_id']===$g['event']&&!$m['archived_at']));try{$service->preview(['operation'=>'save_match','id'=>$active[0]['id'],'data'=>['home_source_match_id'=>$active[0]['id']],'policy'=>'manual'],$actor);throw new RuntimeException('Ciclo aceito');}catch(AdminOperationException $error){check(true,'origem cíclica rejeitada');}

foreach(['handbol','futsal','basquete','queimada','xadrez','volei','quiz','cubo_magico'] as $mod){
    $h=fixture($mod,2,$mod==='quiz'||$mod==='cubo_magico'?'round_robin':'simple');
    if($mod==='quiz'||$mod==='cubo_magico'){
        operation(['operation'=>'regenerate','event_id'=>$h['event'],'modality'=>$mod,'gender'=>'masculino','mode'=>'all','kind'=>'round_robin','policy'=>'restart']);$m=array_values(array_filter($service->snapshot()['matches'],fn($m)=>$m['event_id']===$h['event']&&!$m['archived_at']))[0];$score=json_decode($m['score_data'],true);
        if($mod==='quiz')$score['scores']=[$h['teams'][0]=>10,$h['teams'][1]=>5];else $score['player_attempts']=[$h['players'][0]=>[10,12,11],$h['players'][1]=>[20,22,21]];
        operation(['operation'=>'save_match','id'=>$m['id'],'data'=>['status'=>'encerrada','score_data'=>$score],'policy'=>'update']);check(matchRow($m['id'])['status']==='encerrada',"resultado coletivo $mod");
    }else{$score=$mod==='volei'?['sets'=>[['home'=>25,'away'=>10],['home'=>25,'away'=>12]]]:default_score_data($mod);$id=createMatch($h,0,1,'final',['status'=>'encerrada','home_score'=>2,'away_score'=>0,'score_data'=>$score]);check(matchRow($id)['winner_team_id']===$h['teams'][0],"regras de resultado $mod");}
}
$h=fixture('handbol',4);$pdo->prepare('INSERT INTO teams(event_id,modality,name,class_name,gender,group_name) VALUES(?,?,?,?,?,?)')->execute([$h['event'],'handbol','Equipe feminina QA','', 'feminino','A']);operation(['operation'=>'regenerate','event_id'=>$h['event'],'modality'=>'handbol','gender'=>'masculino','mode'=>'all','kind'=>'simple','policy'=>'restart']);$tree=array_filter($service->snapshot()['matches'],fn($r)=>$r['event_id']===$h['event']&&!$r['archived_at']);check(count($tree)===3&&!array_filter($tree,fn($r)=>$r['gender']!=='masculino'),'sorteio de equipes respeita gênero');
$missingBefore=$service->snapshot();operation(['operation'=>'regenerate','event_id'=>$h['event'],'modality'=>'handbol','gender'=>'masculino','mode'=>'missing','kind'=>'simple','policy'=>'update']);check($missingBefore===$service->snapshot(),'gerar faltantes preserva chave completa e IDs');
$grp=fixture('fifa',4,'groups');$pdo->prepare('UPDATE players SET group_name=? WHERE id=?')->execute(['Z',$grp['players'][0]]);$pdo->prepare('UPDATE players SET group_name=? WHERE id=?')->execute(['Z',$grp['players'][1]]);$pdo->prepare('UPDATE players SET group_name=? WHERE id=?')->execute(['Y',$grp['players'][2]]);$pdo->prepare('UPDATE players SET group_name=? WHERE id=?')->execute(['Y',$grp['players'][3]]);
operation(['operation'=>'regenerate','event_id'=>$grp['event'],'modality'=>'fifa','mode'=>'all','kind'=>'groups','policy'=>'restart']);check($service->snapshot()['players'][$grp['players'][0]]['group_name']==='Z','grupos individuais manuais preservados');
$groupMatches=array_filter($service->snapshot()['matches'],fn($m)=>$m['event_id']===$grp['event']&&!$m['archived_at']);foreach($groupMatches as $m)operation(['operation'=>'save_match','id'=>$m['id'],'data'=>['status'=>'encerrada','home_score'=>2,'away_score'=>0],'policy'=>'update']);
operation(['operation'=>'regenerate','event_id'=>$grp['event'],'modality'=>'fifa','mode'=>'missing','kind'=>'simple','policy'=>'update']);$bracket=array_filter($service->snapshot()['matches'],fn($m)=>$m['event_id']===$grp['event']&&$m['stage']!=='grupo'&&!$m['archived_at']);check(count($bracket)===3&&count(array_filter($bracket,fn($m)=>!empty($m['qualification_sources'])))===2,'vagas geradas registram posições de classificação');
$newPlayer=['name'=>'Excedente QA','team_id'=>$grp['teams'][0]];operation(['operation'=>'save_entity','entity'=>'players','data'=>$newPlayer,'policy'=>'update']);$limitPreview=$service->preview(['operation'=>'save_entity','entity'=>'players','data'=>['name'=>'Terceiro QA','team_id'=>$grp['teams'][0]],'policy'=>'update'],$actor);check(str_contains(implode(' ',$limitPreview['warnings']),'acima do limite'),'limite excedente apresenta aviso e exige justificativa');
$frozen=fixture('clash_royale',4);$plan=$service->preview(['operation'=>'regenerate','event_id'=>$frozen['event'],'modality'=>'clash_royale','mode'=>'all','kind'=>'simple','policy'=>'restart'],$actor);$stmt=$pdo->prepare('SELECT plan_json FROM admin_operation_previews WHERE id=?');$stmt->execute([$plan['preview_id']]);$stored=json_decode($stmt->fetchColumn(),true);$service->execute($plan['preview_id'],'Confirmar o mesmo sorteio','EXCLUIR',$actor);foreach($stored['changes']['matches'] as $id=>$change)check(matchRow((int)$id)==$change['after'],'sorteio confirmado é exatamente o apresentado');
if(in_array('--browser-fixture',$argv,true)){
    $ui=fixture('handbol',4);operation(['operation'=>'regenerate','event_id'=>$ui['event'],'modality'=>'handbol','mode'=>'all','kind'=>'simple','policy'=>'restart']);session_write_close();
    file_put_contents(sys_get_temp_dir().'/interclasse-admin-20261014/browser-fixture.json',json_encode(['event_id'=>$ui['event'],'player_id'=>$ui['players'][0],'session_id'=>session_id(),'database'=>$namespace]));
}
echo "SUCESSO: $passed verificações administrativas.\n";
